import Foundation
import XCTest
@testable import SecutgCore

/// Vectors generated by Web A (`npx tsx dev/secutgVectors.ts`) — the interop oracle for every platform.
enum Vectors {
    static func load(_ name: String) -> [String: Any] {
        guard let url = Bundle.module.url(forResource: name, withExtension: "json", subdirectory: "Vectors"),
              let data = try? Data(contentsOf: url),
              let object = try? JSONSerialization.jsonObject(with: data) as? [String: Any] else {
            XCTFail("missing vector file \(name).json")
            return [:]
        }
        return object
    }

    static func hex(_ text: String) -> [UInt8] { return Hex.decode(text) ?? [] }
    static func b64(_ text: String) -> [UInt8] { return Base64Url.decode(text) ?? [] }
}

/// 2026-09-11T12:00:00Z, same as the vectors
let vectorNowMs: Int64 = 1_789_128_000_000
